create table RC_RULE_TYPE (RULE_ID VARCHAR(50) not null  ,RESTRAINT_TYPE VARCHAR(3) null  ,RULE_DESC VARCHAR(200) null  ,DEAL_FLOW VARCHAR(1) null  ,TERM_TYPE VARCHAR(1) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,TERM VARCHAR(5) null  ,RES_ALL_FLAG VARCHAR(1) null  ,OTH_TERM VARCHAR(5) null  ,OTH_TERM_TYPE VARCHAR(1) null  ,CARD_MEDIUM VARCHAR(20) null  ,RES_OPERATE_FLAG VARCHAR(1) null  ,LIMIT_REF VARCHAR(50) null  ,OTH_RESTRAINT_TYPE VARCHAR(3) null  ,RES_BRANCH_RANGE VARCHAR(1) null  ,CONTROL_TYPE VARCHAR(3) null  ,OTH_DELAY_TERM VARCHAR(5) null  ,OTH_DELAY_TERM_TYPE VARCHAR(1) null  ,OTH_CONTROL_TYPE VARCHAR(3) null  ,REL_VERIFY_FLAG VARCHAR(1) null  , primary key(RULE_ID));